edits.old:
! easy difficulty: the achievement conditions sit at the top of the goal text (the bottom box was easy to miss next to long request dialogue)
$jo9_goal_top = ''
if difficulty_setting = 1 and quest_description_mode = 1: $jo9_goal_top = $func('slave_sell_chek', 'easy_goal_hint', choosen_quest)
if difficulty_setting = 1 and quest_description_mode = 2: $jo9_goal_top = $func('slave_sell_chek', 'easy_goal_hint', 5, jo9_goal_selected_scene)
if $jo9_goal_top ! '': $jo9_goal_top = '<div style="margin:0 0 12px;padding:8px 10px;border:1px solid #7a6a45;background:#f3ead0;color:#191970;font-size:16px;line-height:1.35">' + $jo9_goal_top + '</div>'
*p '<div id = "bg_blue_script_right" class="jo9_goal_scroll"><br><<$jo9_goal_top>><<$quest_list>></div>'

edits.new:
local $jo9_goal_hint = ''
if master_stat_screen = 1 and quest_description_mode = 1 and difficulty_setting = 1: $jo9_goal_hint = $func('slave_sell_chek', 'easy_goal_hint', choosen_quest)
if master_stat_screen = 1 and quest_description_mode = 2 and difficulty_setting = 1: $jo9_goal_hint = $func('slave_sell_chek', 'easy_goal_hint', 5, jo9_goal_selected_scene)
if $jo9_goal_hint ! '':
 *p '<div id="info"><div class="jo9_hint_scroll"><<$jo9_goal_hint>></div></div>'
else
 *p '<div id="info"><<$info_text>></div>'
end
